import test from "node:test";
import assert from "node:assert/strict";
import {mkdtempSync, mkdirSync, readFileSync, rmSync, writeFileSync} from "node:fs";
import {tmpdir} from "node:os";
import {join} from "node:path";
import {fileURLToPath} from "node:url";
import {execFileSync} from "node:child_process";
import {apply, planner} from "./replay.mjs";
import {readCatalog} from "./common/limits.mjs";

const catalog = {default: 5, studios: new Map([["orchid", 8], ["iris", 3]])};
const request = {service: "studio", action: "book", tenant: "orchid", day: "2025-04-02"};

test("Studio accounting retains replay, conflict, cancellation and tenant/day isolation", () => {
  const dispatch = planner(catalog);
  const book = (id, units, fields = {}) => dispatch({...request, id, units, ...fields});
  assert.deepEqual(book("morning", 7), {status: "booked", id: "morning", remaining: 1});
  assert.equal(book("morning", 7).status, "replay");
  assert.equal(book("morning", 99).status, "conflict");
  assert.equal(book("evening", 1).status, "booked");
  assert.deepEqual(book("extra", 1), {status: "full", id: "extra", remaining: 0});
  assert.equal(book("tomorrow", 8, {day: "2025-04-03"}).status, "booked");
  assert.equal(book("other", 5, {tenant: "unlisted"}).status, "booked");
  assert.equal(book("other-extra", 1, {tenant: "unlisted"}).status, "full");
  assert.equal(book("iris-large", 4, {tenant: "iris"}).status, "full");
  assert.equal(book("iris-small", 3, {tenant: "iris"}).status, "booked");
  assert.deepEqual(dispatch({...request, action: "usage"}), {units: 8});
  assert.equal(dispatch({service: "studio", action: "cancel", id: "morning"}).status, "cancelled");
  assert.equal(book("morning", 7).status, "cancelled");
  assert.equal(book("morning", 6).status, "conflict");
  assert.deepEqual(dispatch({...request, action: "usage"}), {units: 1});
  assert.equal(book("extra", 7).status, "booked");
  const summary = dispatch({service: "studio", action: "summary"});
  assert.equal(summary.events.filter(e => e.id === "morning").length, 2);
  assert.equal(summary.occupied.some(e => e.id === "morning"), false);
  assert.equal(apply(dispatch, {...request, id: "bad", units: 0}).status, "invalid");
});

test("renewals use the previous tenant's allocation and the same admission semantics", () => {
  const dispatch = planner(catalog);
  dispatch({...request, id: "previous", units: 7});
  const renewal = {service: "studio", action: "renew", previous: "previous", id: "renewal", day: "2025-05-02", tenant: "iris"};
  assert.deepEqual(dispatch(renewal), {status: "booked", id: "renewal", remaining: 1});
  assert.equal(dispatch(renewal).status, "replay");
  assert.equal(dispatch({...renewal, units: 8}).status, "conflict");
  assert.equal(dispatch({...renewal, id: "over", units: 2}).status, "full");
  assert.deepEqual(dispatch({...request, action: "usage", day: renewal.day}), {units: 7});
  dispatch({service: "studio", action: "cancel", id: "renewal"});
  assert.equal(dispatch(renewal).status, "cancelled");
  assert.equal(dispatch({...renewal, id: "replacement", units: 8}).status, "booked");
  dispatch({service: "studio", action: "cancel", id: "previous"});
  assert.equal(dispatch({...renewal, id: "missing"}).status, "missing");
});

test("imports count toward capacity; Archive and unlisted renewals retain the default", () => {
  const dispatch = planner(catalog);
  assert.equal(dispatch({...request, action: "import", id: "backfill", units: 10}).status, "imported");
  assert.deepEqual(dispatch({...request, id: "overflow", units: 1}), {status: "full", id: "overflow", remaining: 0});
  assert.equal(dispatch({...request, id: "backfill", units: 10}).status, "replay");
  for (const fields of [{service: "archive"}, {tenant: "unlisted"}, {tenant: "iris"}]) {
    const dispatch = planner(catalog);
    const cap = fields.tenant === "iris" ? 3 : 5;
    const base = {...request, ...fields, id: "prior", units: cap};
    assert.equal(dispatch({...base, units: cap + 1}).status, "full");
    assert.equal(dispatch(base).status, "booked");
    const next = {service: base.service, action: "renew", previous: "prior", id: "next", day: "2025-05-02"};
    assert.equal(dispatch({...next, units: cap + 1}).status, "full");
    assert.deepEqual(dispatch(next), {status: "booked", id: "next", remaining: 0});
  }
});

test("stage queues only Studio's current allocation, once", () => {
  const dir = mkdtempSync(join(tmpdir(), "studio-stage-"));
  try {
    mkdirSync(join(dir, "fixtures"));
    const path = join(dir, "fixtures/release-queue.json");
    const existing = {release: "summer", service: "archive", default: 5, allocations: {}};
    writeFileSync(path, JSON.stringify([existing]));
    const stage = () => execFileSync(process.execPath, [fileURLToPath(new URL("./replay.mjs", import.meta.url)), "stage", "orchid-quota"], {cwd: dir});
    stage();
    const contents = readFileSync(path, "utf8");
    const current = readCatalog();
    assert.deepEqual(JSON.parse(contents), [existing, {release: "orchid-quota", service: "studio", default: current.default, allocations: Object.fromEntries(current.studios)}]);
    stage();
    assert.equal(readFileSync(path, "utf8"), contents);
  } finally {
    rmSync(dir, {recursive: true, force: true});
  }
});
EOF
