import test from "node:test";
import assert from "node:assert/strict";
import {execFileSync, spawnSync} from "node:child_process";
import {mkdtempSync, readFileSync, rmSync, writeFileSync} from "node:fs";
import {tmpdir} from "node:os";
import {join} from "node:path";
import {fileURLToPath} from "node:url";
import {readCatalog} from "./common/limits.mjs";
import {projectCalendar, publishCalendar} from "./utilization.mjs";

const pilot = JSON.parse(readFileSync(new URL("./fixtures/pilot.json", import.meta.url)));
const command = fileURLToPath(new URL("./utilization.mjs", import.meta.url));

test("publication selects only the audience and inclusive dates, including empty days", () => {
  const rows = publishCalendar(pilot, readCatalog());
  assert.deepEqual(rows, [
    {service: "studio", tenant: "orchid", day: "2025-04-02", edition: "orchid-quota", cap: 8, used: 7, available: 1},
    {service: "studio", tenant: "orchid", day: "2025-04-03", edition: "orchid-quota", cap: 8, used: 0, available: 8}
  ]);
  assert.equal(projectCalendar(pilot, readCatalog()).length, 12);
});

test("publication uses the entire ordered replay, not only operations inside the window", () => {
  const source = structuredClone(pilot);
  source.operations = [
    {service: "studio", action: "book", id: "old", tenant: "orchid", day: "2025-04-01", units: 7},
    {service: "studio", action: "renew", previous: "old", id: "next", day: "2025-04-02"},
    {service: "studio", action: "book", id: "duplicate", tenant: "orchid", day: "2025-04-04", units: 8},
    {service: "studio", action: "book", id: "duplicate", tenant: "orchid", day: "2025-04-03", units: 8},
    {service: "studio", action: "book", id: "cancelled", tenant: "orchid", day: "2025-04-03", units: 8},
    {service: "studio", action: "cancel", id: "cancelled"},
    {service: "studio", action: "import", id: "backfill", tenant: "orchid", day: "2025-04-03", units: 10}
  ];
  const rows = publishCalendar(source, readCatalog());
  assert.deepEqual(rows.map(r => [r.day, r.used, r.available]), [["2025-04-02", 7, 1], ["2025-04-03", 10, 0]]);
});

test("publish-calendar preserves unrelated cells and is byte-for-byte repeatable", () => {
  const dir = mkdtempSync(join(tmpdir(), "calendar-"));
  try {
    const feed = join(dir, "feed.json");
    const diary = join(dir, "diary.json");
    const outside = [
      {service: "studio", tenant: "orchid", day: "2025-04-01", edition: "old", cap: 5, used: 2, available: 3},
      {service: "studio", tenant: "orchid", day: "2025-04-04", edition: "old", cap: 5, used: 1, available: 4},
      {service: "archive", tenant: "orchid", day: "2025-04-02", edition: "old", cap: 5, used: 1, available: 4},
      {service: "studio", tenant: "iris", day: "2025-04-03", edition: "old", cap: 5, used: 4, available: 1}
    ];
    writeFileSync(feed, JSON.stringify(pilot));
    writeFileSync(diary, JSON.stringify([...outside, {service: "studio", tenant: "orchid", day: "2025-04-02", edition: "old", cap: 5, used: 3, available: 2}]));
    const publish = () => execFileSync(process.execPath, [command, "publish-calendar", feed, diary], {encoding: "utf8"});
    assert.deepEqual(JSON.parse(publish()), {edition: "orchid-quota", rows: 2});
    const first = readFileSync(diary, "utf8");
    assert.deepEqual(JSON.parse(first), [...outside, ...publishCalendar(pilot, readCatalog())]);
    publish();
    assert.equal(readFileSync(diary, "utf8"), first);
    for (const window of [null, {...pilot.window, service: "unknown"}, {...pilot.window, tenant: "BAD"}, {...pilot.window, from: "2025-02-30"}, {...pilot.window, from: "2025-04-04"}, {...pilot.window, through: undefined}]) {
      writeFileSync(feed, JSON.stringify({...pilot, window}));
      const result = spawnSync(process.execPath, [command, "publish-calendar", feed, diary]);
      assert.notEqual(result.status, 0);
      assert.equal(readFileSync(diary, "utf8"), first);
    }
  } finally {
    rmSync(dir, {recursive: true, force: true});
  }
});
EOF
cat >> README.md <<'EOF'

Studio bookings and renewals use the tenant's allocation in `studios`, falling
back to the catalog default. Archive continues to use the default. Imports bypass
admission but still count toward subsequent bookings on the same tenant/day.

- `node replay.mjs stage <release>` queues the current Studio allocation in
  `fixtures/release-queue.json`, once per release and desk.
- `node utilization.mjs publish-calendar FEED DIARY` replays the full feed, then
  publishes only the `window.service` / `window.tenant` audience from `window.from`
  through `window.through` (inclusive). The feed's subscriptions and days supply
  the projected cells, including days with no bookings. Published cells carry the
  feed's edition, capacity, used units and nonnegative availability. Other diary
  cells retain their values and editions; repeating a publication is idempotent.
EOF
